import org.apache.commons.lang3.text.ExtendedMessageFormat;
import java.util.*;

public class QuoteCheck {
    public static void main(String[] args) throws Exception {
        try {
            ExtendedMessageFormat emf = new ExtendedMessageFormat("'unterminated {0}");
            System.out.println("no registry toPattern=" + emf.toPattern());
        } catch (Exception e) {
            System.out.println("no registry exception: " + e);
        }
        Map<String, org.apache.commons.lang3.text.FormatFactory> reg = new HashMap<String, org.apache.commons.lang3.text.FormatFactory>();
        reg.put("x", new org.apache.commons.lang3.text.FormatFactory() {
            public java.text.Format getFormat(String name, String arguments, Locale locale) {
                return new java.text.SimpleDateFormat();
            }
        });
        try {
            ExtendedMessageFormat emf = new ExtendedMessageFormat("'unterminated {0}", reg);
            System.out.println("with registry toPattern=" + emf.toPattern());
        } catch (Exception e) {
            System.out.println("with registry exception: " + e);
        }

        try {
            ExtendedMessageFormat emf2 = new ExtendedMessageFormat("{0,number,integer}", reg);
            System.out.println(emf2.format(new Object[]{Integer.valueOf(1234)}));
        } catch (Exception e) {
            System.out.println("exc2: " + e);
        }
    }
}
EOF
javac -cp target/classes -d _tools/scratch _tools/scratch/QuoteCheck.java
java -cp _tools/scratch:target/classes QuoteCheck
